const header=document.querySelector('.site-header');const menu=document.querySelector('.menu');if(menu){menu.addEventListener('click',()=>{const open=header.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));});}document.querySelectorAll('.lead-form').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const status=form.querySelector('.form-status');if(form.elements.website?.value)return;const data=new FormData(form);const works=data.getAll('werkzaamheden').join(', ');const type=form.dataset.form;const lines=type==='storing'?["Goedendag, ik wil een elektrische storing melden.","Naam: "+data.get('naam'),"Telefoon: "+data.get('telefoon'),"Locatie: "+data.get('postcode')+' '+data.get('plaats'),"Type: "+data.get('storing'),"Omschrijving: "+data.get('omschrijving')]:["Goedendag, ik wil graag een "+(type==='zakelijk'?'zakelijke aanvraag':'offerteaanvraag')+" indienen.","Naam: "+data.get('voornaam')+' '+data.get('achternaam'),"Bedrijf: "+(data.get('bedrijf')||'-'),"E-mail: "+data.get('email'),"Telefoon: "+data.get('telefoon'),"Adres: "+data.get('postcode')+' '+data.get('huisnummer')+(data.get('toevoeging')||'')+', '+data.get('plaats'),"Klanttype: "+data.get('klanttype'),"Werkzaamheden: "+(works||'Niet gekozen'),"Planning: "+data.get('planning'),"Contactvoorkeur: "+data.get('contactvoorkeur'),"Omschrijving: "+data.get('omschrijving')];status.textContent='WhatsApp wordt geopend. Voeg daar eventueel uw foto’s toe en druk op verzenden.';window.open('https://wa.me/31613271261?text='+encodeURIComponent(lines.join('\n')),'_blank','noopener');}));